import { describe, it, expect } from "vitest";

describe("Claim Office", () => {
  describe("Quote – Base premiums", () => {
    it.todo("returns 5 G for an empty item list (processing fee only)");
    it.todo("computes base premium for a single sword");
    it.todo("computes base premium for a single amulet");
    it.todo("computes base premium for a single staff");
    it.todo("computes base premium for a single potion");
    it.todo("computes base premium for a single rune component");
  });

  describe("Quote – Component building blocks", () => {
    it.todo("applies block discount for exactly 3 alike runes");
    it.todo("does not apply block for 4 runes");
    it.todo("applies two separate blocks for 3 runes and 3 moonstones");
  });

  describe("Quote – Item-specific modifiers", () => {
    it.todo("adds 50% curse surcharge on a cursed sword");
    it.todo("adds 30% high-enchantment surcharge for enchantment >= 5");
    it.todo("applies both curse and high-enchantment surcharges");
  });

  describe("Quote – Policy-wide modifiers", () => {
    it.todo("applies 20% loyalty discount for customer with >= 2 years");
    it.todo("applies 10% first insurance surcharge");
    it.todo("applies 15% follow-up contract discount on second quote");
  });

  describe("Quote – Integration and rounding", () => {
    it.todo("newcomer with cursed sword pays 165 G");
    it.todo("long-standing customer second contract pays 160 G");
  });

  describe("Claim – Basic processing", () => {
    it.todo("standard reimbursement: full damage minus 100 G deductible");
    it.todo("high enchantment >= 8: 50% reimbursement then deductible");
    it.todo("dragon material: full reimbursement then deductible");
  });

  describe("Claim – Cap and multiple damages", () => {
    it.todo("caps total payout at twice the insurance sum across claims");
    it.todo("applies deductible per damaged item in a single incident");
  });

  describe("Claim – Validation errors", () => {
    it.todo("rejects claim with unknown item type");
    it.todo("rejects claim with more damages than insured items");
    it.todo("rejects claim with negative damage amount");
  });

  describe("Quote – Validation errors", () => {
    it.todo("rejects quote with unknown item type");
  });
});

