import { describe, it, expect } from "vitest";
import { processScenario } from "./claim-office.js";

describe("Claim Office", () => {
  describe("Quote - base premium", () => {
    it("returns 5 G for an empty item list (processing fee only)", () => {
      const result = processScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote" as const, items: [] }],
      });
      expect(result.results[0]).toEqual({ premium: 5 });
    });
    it.todo("should return correct premium for a single sword (100 base + 10 first insurance + 5 fee = 115 G)");
    it.todo("should return correct premium for a single amulet (60 base + 6 first insurance + 5 fee = 71 G)");
    it.todo("should return correct premium for a single staff (80 base + 8 first insurance + 5 fee = 93 G)");
    it.todo("should return correct premium for a single potion (40 base + 4 first insurance + 5 fee = 49 G)");
    it.todo("should return correct premium for multiple different items");
  });

  describe("Quote - components", () => {
    it.todo("should return correct premium for a single rune (25 base + first insurance + fee)");
    it.todo("should return correct premium for 2 runes (50 base + first insurance + fee)");
    it.todo("should apply building block discount for exactly 3 alike runes (60 base)");
    it.todo("should not apply block discount for 4 runes (100 base)");
    it.todo("should not apply block for 2 runes and 1 moonstone (different types, 75 base)");
    it.todo("should apply two separate blocks for 3 runes and 3 moonstones (120 base)");
  });

  describe("Quote - item-specific modifiers", () => {
    it.todo("should add 50% cursed surcharge on the cursed item base premium only");
    it.todo("should add 30% high enchantment surcharge for enchantment level 5 or above");
    it.todo("should not add high enchantment surcharge for enchantment level 4");
    it.todo("should apply both cursed and high enchantment surcharges on the same item");
    it.todo("should apply item-specific modifier only to affected item in multi-item policy");
  });

  describe("Quote - policy-wide modifiers", () => {
    it.todo("should apply 20% loyalty discount for customer with 2 or more years");
    it.todo("should not apply loyalty discount for customer with less than 2 years");
    it.todo("should apply 10% first insurance surcharge (always applies to every item)");
    it.todo("should apply 15% follow-up discount on second quote step");
    it.todo("should not apply follow-up discount on first quote step");
  });

  describe("Quote - integration", () => {
    it.todo("should compute 165 G for newcomer with cursed sword (0 years, first contract)");
    it.todo("should compute 160 G for long-standing customer second contract (3 years, cursed sword ench 7)");
    it.todo("should round premium up in MHPCO favor");
  });

  describe("Claim - basic payout", () => {
    it.todo("should apply 100 G deductible per damaged item for standard reimbursement");
    it.todo("should fully reimburse standard item damage minus deductible");
    it.todo("should reimburse damage to a rune minus deductible (standard, no special clauses)");
    it.todo("should handle multiple damaged items each with their own deductible");
  });

  describe("Claim - special clauses", () => {
    it.todo("should reimburse at 50% of damage amount for enchantment level 8 or higher then deductible");
    it.todo("should fully reimburse dragon material items then deductible");
    it.todo("should apply 50% rule when both enchantment >= 8 and dragon material");
  });

  describe("Claim - cap", () => {
    it.todo("should cap total payout at 2x insurance sum of the policy");
    it.todo("should track remaining cap after a claim payout");
    it.todo("should reduce payout to remaining cap on successive claims");
  });

  describe("Claim - payout rounding", () => {
    it.todo("should round payout down in MHPCO favor");
  });

  describe("Claim - validation", () => {
    it.todo("should error when damage item type is not in the policy");
    it.todo("should error when damage entries of a type exceed count in policy");
    it.todo("should error when damage amount is negative");
  });

  describe("Quote - validation", () => {
    it.todo("should error for unknown item type in quote");
  });

  describe("CLI - sequential steps", () => {
    it.todo("should process a quote step and return premium in results");
    it.todo("should process a claim step referencing a prior quote and return payout and remainingCap");
  });
});

